// The Error Trigger sends either { execution, workflow } or, when a trigger failed, { trigger, workflow }.
const e = $input.first().json;
const wfName = e.workflow?.name || 'Unknown workflow';
const err = e.execution?.error || e.trigger?.error || {};
const message = String(err.message || 'No error message').slice(0, 600);
const node = e.execution?.lastNodeExecuted || err.node?.name || (e.trigger ? 'trigger' : 'unknown');
const when = new Date().toISOString().replace('T', ' ').slice(0, 19) + ' UTC';
const url = e.execution?.url || '';
const mode = e.execution?.mode || (e.trigger ? 'trigger' : '');

const lines = [
  `Workflow: ${wfName}`,
  `Failed node: ${node}`,
  `Error: ${message}`,
  `When: ${when}${mode ? ` (${mode})` : ''}`,
  url ? `Execution: ${url}` : 'Execution: none (the trigger itself failed — check its credential or settings)',
];
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const html = `<h3>❌ ${esc(wfName)} failed</h3><ul>${lines.slice(1).map((l) => `<li>${esc(l)}</li>`).join('')}</ul>`
  + (url ? `<p><a href="${esc(url)}">Open the execution</a></p>` : '');

return [{ json: { subject: `❌ n8n: ${wfName} failed`, message: lines.join('\n'), html } }];
